"""
Client for Qwen 3.5 Vision via Ollama on Spark.

Replaces the custom Qwen 2.5-VL-3B grounding server with direct Ollama API calls.
Returns results in the same format as GroundingClient for drop-in compatibility.

Usage:
    from common.ollama_client import OllamaVisionClient

    client = OllamaVisionClient("http://spark:11434")
    result = client.ground(image_bytes, "the red block", width=640, height=480)
    # result = {"success": True, "bbox": [x1,y1,x2,y2], "center": [cx,cy], ...}
"""

import base64
import json
import logging
import re
import time
import urllib.request
from typing import Optional

logger = logging.getLogger(__name__)

DEFAULT_SERVER_URL = "http://spark:11434"
DEFAULT_MODEL = "qwen3.5:122b"


class OllamaVisionClient:
    def __init__(
        self,
        server_url: str = DEFAULT_SERVER_URL,
        model: str = DEFAULT_MODEL,
        timeout: float = 60.0,
    ):
        self.server_url = server_url.rstrip("/")
        self.model = model
        self.timeout = timeout

    def health(self) -> bool:
        """Check if Ollama has the model available."""
        try:
            req = urllib.request.Request(f"{self.server_url}/api/tags")
            with urllib.request.urlopen(req, timeout=5) as resp:
                data = json.loads(resp.read())
                models = [m.get("name", "") for m in data.get("models", [])]
                # Check for exact match or prefix match (e.g. "qwen3.5:35b" in "qwen3.5:35b-q4_K_M")
                model_base = self.model.split(":")[0]
                for m in models:
                    if m == self.model or m.startswith(self.model) or m.startswith(model_base + ":"):
                        return True
                logger.warning(f"Model {self.model} not found. Available: {models}")
                return False
        except Exception as e:
            logger.warning(f"Ollama health check failed: {e}")
            return False

    def ground(
        self,
        image_jpeg: bytes,
        query: str,
        width: int = 0,
        height: int = 0,
    ) -> dict:
        """
        Ground a natural language query in an image using Ollama vision.

        Returns dict compatible with GroundingClient:
            {success, bbox, center, inference_ms, raw_output, error}
        """
        prompt = (
            f"Find '{query}' in this {width}x{height} image. "
            f"Return ONLY a JSON object: {{\"bbox\": [x1, y1, x2, y2]}} "
            f"where coordinates are in pixels (0-{width-1} for x, 0-{height-1} for y). "
            f"No other text."
        )

        t0 = time.time()
        response = self._chat(image_jpeg, prompt)
        inference_ms = round((time.time() - t0) * 1000, 1)

        if response is None:
            return {"success": False, "error": "Ollama request failed", "inference_ms": inference_ms}

        raw_text = response.get("message", {}).get("content", "")
        bbox = self._parse_bbox(raw_text, width, height)

        if bbox is None:
            return {
                "success": False,
                "error": "Could not parse bbox from response",
                "raw_output": raw_text,
                "inference_ms": inference_ms,
            }

        cx = int((bbox[0] + bbox[2]) / 2)
        cy = int((bbox[1] + bbox[3]) / 2)

        return {
            "success": True,
            "bbox": bbox,
            "center": [cx, cy],
            "raw_output": raw_text,
            "inference_ms": inference_ms,
        }

    def describe_scene(self, image_jpeg: bytes) -> dict:
        """
        Describe all objects visible in the workspace image.

        Returns:
            {success, objects: [{name, color, position}], raw_output, inference_ms}
        """
        prompt = (
            "List all objects on the table in this robot workspace image. "
            "Return ONLY a JSON object: {\"objects\": [{\"name\": \"...\", \"color\": \"...\", "
            "\"position\": \"left/center/right\"}]}. No other text."
        )

        t0 = time.time()
        response = self._chat(image_jpeg, prompt)
        inference_ms = round((time.time() - t0) * 1000, 1)

        if response is None:
            return {"success": False, "error": "Ollama request failed", "inference_ms": inference_ms}

        raw_text = response.get("message", {}).get("content", "")
        parsed = self._parse_json(raw_text)

        if parsed is None or "objects" not in parsed:
            return {
                "success": False,
                "error": "Could not parse scene description",
                "raw_output": raw_text,
                "inference_ms": inference_ms,
            }

        return {
            "success": True,
            "objects": parsed["objects"],
            "raw_output": raw_text,
            "inference_ms": inference_ms,
        }

    # Valid skills the VLM can output
    VALID_SKILLS = {"pick", "place", "push", "home", "done"}

    def next_skill(
        self,
        image_jpeg: bytes,
        task: str,
        history: list[dict],
        width: int = 640,
        height: int = 480,
    ) -> dict:
        """
        Ask the VLM for the next single skill to execute.

        Args:
            image_jpeg: Current camera frame as JPEG bytes
            task: Natural language task instruction
            history: Previous steps [{step, skill, object, result, ...}, ...]
            width: Image width in pixels
            height: Image height in pixels

        Returns:
            {success, skill, params, reasoning, raw_output, inference_ms}
        """
        prompt = self._build_next_skill_prompt(task, history, width, height)

        t0 = time.time()
        response = self._chat(image_jpeg, prompt, temperature=0.3)
        inference_ms = round((time.time() - t0) * 1000, 1)

        if response is None:
            return {"success": False, "error": "Ollama request failed",
                    "inference_ms": inference_ms}

        raw_text = response.get("message", {}).get("content", "")
        logger.info(f"next_skill raw response ({len(raw_text)} chars, "
                     f"{inference_ms:.0f}ms): {raw_text[:300]}")
        reasoning = self._extract_think(raw_text)
        clean_text = self._strip_think(raw_text)
        parsed = self._parse_json(clean_text)

        if parsed is None or "skill" not in parsed:
            return {
                "success": False,
                "error": "Could not parse skill from response",
                "raw_output": raw_text,
                "reasoning": reasoning,
                "inference_ms": inference_ms,
            }

        skill = parsed["skill"]
        if skill not in self.VALID_SKILLS:
            return {
                "success": False,
                "error": f"Unknown skill: {skill}",
                "raw_output": raw_text,
                "reasoning": reasoning,
                "inference_ms": inference_ms,
            }

        # Extract params (everything except "skill")
        params = {k: v for k, v in parsed.items() if k != "skill"}

        # Validate pixel coordinates are in bounds
        for key in ("pixel_x", "pixel_y"):
            if key in params:
                try:
                    params[key] = int(params[key])
                except (ValueError, TypeError):
                    pass

        return {
            "success": True,
            "skill": skill,
            "params": params,
            "reasoning": reasoning,
            "raw_output": raw_text,
            "inference_ms": inference_ms,
        }

    def _build_next_skill_prompt(
        self,
        task: str,
        history: list[dict],
        width: int,
        height: int,
    ) -> str:
        """Build the prompt for next_skill()."""
        history_str = json.dumps(history[-5:], indent=2) if history else "None (first step)"

        return f"""You are controlling a Franka Panda robot arm. You see the workspace from a fixed camera above the table.

The image is {width}x{height} pixels. The camera looks down at the table from the front of the robot. Objects closer to the bottom of the image are closer to the robot (reachable). Objects at the top are farther away.

Available skills — output exactly ONE as a JSON object:

1. pick — Pick up an object from the table
   {{"skill": "pick", "pixel_x": <int>, "pixel_y": <int>, "object": "<name>", "grasp_width": 0.03}}
   pixel_x, pixel_y = center of the object to pick IN THE IMAGE
   grasp_width = gripper opening in meters (0.03 for small blocks, 0.06 for larger objects)

2. place — Place a held object on the table
   {{"skill": "place", "pixel_x": <int>, "pixel_y": <int>}}
   pixel_x, pixel_y = where to place the object IN THE IMAGE

3. push — Push an object sideways
   {{"skill": "push", "pixel_x": <int>, "pixel_y": <int>, "push_dx": <float>, "push_dy": <float>}}
   push_dx, push_dy = push distance in meters (typically ±0.05)

4. home — Return arm to safe home position
   {{"skill": "home"}}

5. done — Task is complete, no more actions needed
   {{"skill": "done"}}

Rules:
- You MUST pick an object before you can place it.
- After placing, verify the task is complete before saying "done".
- Return "home" before "done" so the arm is out of the way.
- For pixel coordinates, point to the CENTER of the object.
- Output ONLY a single JSON object. No other text.

Task: {task}

Previous actions:
{history_str}

Look at the image. What is the next skill to execute?"""

    def plan_skills(
        self,
        image_jpeg: bytes,
        task: str,
        available_objects: Optional[list[dict]] = None,
    ) -> dict:
        """Plan a full skill sequence from image + task. Uses next_skill internally."""
        return self.next_skill(image_jpeg, task, history=[],
                               width=640, height=480)

    def _chat(self, image_jpeg: bytes, prompt: str,
              temperature: Optional[float] = None) -> Optional[dict]:
        """Send a vision chat request to Ollama."""
        img_b64 = base64.b64encode(image_jpeg).decode()

        options = {"num_predict": 4096}
        if temperature is not None:
            options["temperature"] = temperature

        payload = json.dumps({
            "model": self.model,
            "messages": [
                {
                    "role": "user",
                    "content": prompt,
                    "images": [img_b64],
                }
            ],
            "stream": False,
            "options": options,
        }).encode()

        req = urllib.request.Request(
            f"{self.server_url}/api/chat",
            data=payload,
            headers={"Content-Type": "application/json"},
        )

        try:
            with urllib.request.urlopen(req, timeout=self.timeout) as resp:
                return json.loads(resp.read())
        except Exception as e:
            logger.error(f"Ollama chat request failed: {e}")
            return None

    def _parse_bbox(self, raw_text: str, width: int, height: int) -> Optional[list[int]]:
        """Parse bounding box from model output, handling various formats.

        Strips <think> blocks, then tries:
        1. JSON object with "bbox" key
        2. JSON array [x1, y1, x2, y2]
        3. Normalized coordinates (0-1 range) → scale to pixels
        """
        text = self._strip_think(raw_text)

        # Try JSON object with bbox key
        parsed = self._parse_json(text)
        if parsed and "bbox" in parsed:
            bbox = parsed["bbox"]
            if isinstance(bbox, list) and len(bbox) == 4:
                bbox = [self._to_num(v) for v in bbox]
                if all(v is not None for v in bbox):
                    return self._maybe_denormalize(bbox, width, height)

        # Try bare JSON array
        match = re.search(r'\[[\s]*[\d.]+[\s]*,[\s]*[\d.]+[\s]*,[\s]*[\d.]+[\s]*,[\s]*[\d.]+[\s]*\]', text)
        if match:
            try:
                arr = json.loads(match.group())
                if len(arr) == 4:
                    bbox = [self._to_num(v) for v in arr]
                    if all(v is not None for v in bbox):
                        return self._maybe_denormalize(bbox, width, height)
            except json.JSONDecodeError:
                pass

        # Try comma-separated numbers
        numbers = re.findall(r'[\d.]+', text)
        if len(numbers) >= 4:
            bbox = [self._to_num(n) for n in numbers[:4]]
            if all(v is not None for v in bbox):
                return self._maybe_denormalize(bbox, width, height)

        return None

    def _maybe_denormalize(self, bbox: list, width: int, height: int) -> list[int]:
        """If all coords are 0-1 (normalized), scale to pixel coords."""
        if all(0 <= v <= 1.0 for v in bbox) and width > 0 and height > 0:
            return [
                int(bbox[0] * width),
                int(bbox[1] * height),
                int(bbox[2] * width),
                int(bbox[3] * height),
            ]
        return [int(v) for v in bbox]

    @staticmethod
    def _to_num(v) -> Optional[float]:
        try:
            return float(v)
        except (ValueError, TypeError):
            return None

    @staticmethod
    def _strip_think(text: str) -> str:
        """Remove <think>...</think> blocks from reasoning models."""
        return re.sub(r'<think>.*?</think>', '', text, flags=re.DOTALL).strip()

    @staticmethod
    def _extract_think(text: str) -> str:
        """Extract content from <think>...</think> blocks."""
        matches = re.findall(r'<think>(.*?)</think>', text, flags=re.DOTALL)
        return "\n".join(m.strip() for m in matches) if matches else ""

    @staticmethod
    def _parse_json(text: str) -> Optional[dict]:
        """Extract first JSON object from text."""
        text = OllamaVisionClient._strip_think(text)

        # Try direct parse
        try:
            return json.loads(text)
        except json.JSONDecodeError:
            pass

        # Try extracting from markdown code block
        match = re.search(r'```(?:json)?\s*(\{.*?\})\s*```', text, re.DOTALL)
        if match:
            try:
                return json.loads(match.group(1))
            except json.JSONDecodeError:
                pass

        # Try finding any JSON object
        match = re.search(r'\{[^{}]*\}', text, re.DOTALL)
        if match:
            try:
                return json.loads(match.group())
            except json.JSONDecodeError:
                pass

        return None

