        text = self._strip_think(raw_text)

        # Try JSON object with bbox key
        parsed = self._parse_json(text)
        if parsed and "bbox" in parsed:
            bbox = parsed["bbox"]
            if isinstance(bbox, list) and len(bbox) == 4:
                bbox = [self._to_num(v) for v in bbox]
                if all(v is not None for v in bbox):
                    return self._maybe_denormalize(bbox, width, height)

        # Try bare JSON array
        match = re.search(r'\[[\s]*[\d.]+[\s]*,[\s]*[\d.]+[\s]*,[\s]*[\d.]+[\s]*,[\s]*[\d.]+[\s]*\]', text)
        if match:
            try:
                arr = json.loads(match.group())
                if len(arr) == 4:
                    bbox = [self._to_num(v) for v in arr]
                    if all(v is not None for v in bbox):
                        return self._maybe_denormalize(bbox, width, height)
            except json.JSONDecodeError:
                pass

        # Try comma-separated numbers
        numbers = re.findall(r'[\d.]+', text)
        if len(numbers) >= 4:
            bbox = [self._to_num(n) for n in numbers[:4]]
            if all(v is not None for v in bbox):
                return self._maybe_denormalize(bbox, width, height)

        return None

    def _maybe_denormalize(self, bbox: list, width: int, height: int) -> list[int]:
        """If coords are normalized (0-1 or 0-1000), scale to pixel coords.

        Qwen vision models commonly output coordinates in 0-1000 normalized
        space regardless of the actual image dimensions.
        """
        if width <= 0 or height <= 0:
            return [int(v) for v in bbox]

        # Check for 0-1 normalized
        if all(0 <= v <= 1.0 for v in bbox):
            return [
                int(bbox[0] * width),
                int(bbox[1] * height),
                int(bbox[2] * width),
                int(bbox[3] * height),
            ]

        # Check for 0-1000 normalized (Qwen standard)
        # Detect if coords exceed image dims or are all in 0-1000 range
        x_coords = [bbox[0], bbox[2]]
        y_coords = [bbox[1], bbox[3]]
        if (any(y > height for y in y_coords) or any(x > width for x in x_coords)
                or all(0 <= v <= 1000 for v in bbox)):
            # Likely 0-1000 normalized
            if max(bbox) > 1:  # not 0-1 range
                return [
                    int(bbox[0] / 1000 * width),
                    int(bbox[1] / 1000 * height),
                    int(bbox[2] / 1000 * width),
                    int(bbox[3] / 1000 * height),
                ]

        return [int(v) for v in bbox]

    @staticmethod
    def _to_num(v) -> Optional[float]:
        try:
            return float(v)
