def pick_at_servo(
    self,
    x: float,
    y: float,
    target_color: str = "blue",
    grasp_width: float = 0.03,
    grasp_force: float = 70.0,
    servo_height: float = 0.12,
    yaw: float = 0.0,
) -> dict:
    """Pick an object using D405 wrist camera visual servo for centering.

    Two-phase approach:
    1. Move above approximate position (from D435 or estimate)
    2. D405 servo loop centers gripper over the block
    3. Lower to grasp height and close gripper

    Args:
        x, y: Approximate block position (±4cm is fine)
        target_color: Block color for HSV detection (blue/red/green/orange)
        grasp_width: Expected object width for gripper (meters)
        grasp_force: Grasp force in Newtons
        servo_height: Height above table for servo loop (meters)
        yaw: Wrist rotation in radians
    """
    if not self._connected:
        return {"success": False, "error": "Not connected to robot"}

    from common.wrist_servo import WristServo

    steps = []
    servo = WristServo(target_color=target_color)

    # 1. Open gripper
    try:
        self.gripper_move(0.08)
        steps.append({"action": "open_gripper", "success": True})
    except Exception as e:
        return {"success": False, "error": f"gripper_move failed: {e}"}

    # 2. Move above approximate position
    try:
        result = self.move_cartesian_ik(
            x=x, y=y, z=servo_height,
            yaw=yaw, confirmed=True,
        )
        steps.append({"action": "move_above", "position": (x, y, servo_height),
                      "actual": result.get("actual_position")})
    except Exception as e:
        return {"success": False, "error": f"move_above failed: {e}", "steps": steps}

    # 3. Connect D405 wrist camera
    if not servo.connect_camera():
        return {"success": False, "error": "D405 camera connection failed",
                "steps": steps}

    # 4. Run servo loop
    try:
        def move_fn(nx, ny, nz):
            self.move_cartesian_ik(x=nx, y=ny, z=nz, yaw=yaw, confirmed=True)

        def get_pos_fn():
            state = self._rt_client.get_state()
            ee = state.get("O_T_EE", None)
            if ee is not None:
                import numpy as np
                T = np.array(ee).reshape(4, 4).T
                return (T[0, 3], T[1, 3], T[2, 3])
            return (x, y, servo_height)

        servo_result = servo.run_servo(
            move_fn=move_fn,
            get_pos_fn=get_pos_fn,
            height_m=servo_height,
        )
        steps.append({
            "action": "wrist_servo",
            "converged": servo_result["converged"],
            "iterations": servo_result["iterations"],
            "final_position": servo_result.get("final_position"),
            "history": servo_result.get("history", []),
        })
    finally:
        servo.disconnect_camera()

    if not servo_result["converged"]:
        logger.warning("Wrist servo did not converge — attempting pick anyway")

    # 5. Get corrected position and do the pick
    final_pos = servo_result.get("final_position", (x, y, servo_height))
    corrected_x, corrected_y = final_pos[0], final_pos[1]
    logger.info(f"Servo corrected position: ({corrected_x:.4f}, {corrected_y:.4f})")

    # 6. Lower to grasp height incrementally and grasp
    try:
        # Lower from servo height to grasp
        pick_result = self.pick_at(
            x=corrected_x, y=corrected_y,
            grasp_width=grasp_width,
            grasp_force=grasp_force,
            yaw=yaw,
            approach_height=servo_height,
        )
        steps.append({"action": "pick", "result": pick_result})

        return {
            "success": pick_result.get("success", False),
            "gripper_width": pick_result.get("gripper_width"),
            "corrected_position": (corrected_x, corrected_y),
            "original_position": (x, y),
            "servo_iterations": servo_result["iterations"],
            "servo_converged": servo_result["converged"],
            "steps": steps,
        }

    except Exception as e:
        logger.exception("pick_at_servo: pick phase failed")
        try:
            self.recover()
        except Exception:
            pass
        return {"success": False, "error": str(e), "steps": steps}

