def move_fn(nx, ny, nz):
    self.move_cartesian_ik(x=nx, y=ny, z=nz, yaw=yaw, confirmed=True)

def get_pos_fn():
    state = self._rt_client.get_state()
    ee = state.get("O_T_EE", None)
    if ee is not None:
        import numpy as np
        T = np.array(ee).reshape(4, 4).T
        return (T[0, 3], T[1, 3], T[2, 3])
    return (x, y, servo_height)

servo_result = servo.run_servo(
    move_fn=move_fn,
    get_pos_fn=get_pos_fn,
    height_m=servo_height,
)

